            ("a Make public of 12 ₳", Purpose::Pay, to_address(12_000_000)),
            ("a Send of 12 ₳ to a Seedelf", Purpose::Pay, Vec::new()),
        ];
        let describe = |inputs: &[UtxoResponse]| -> String {
            let m = inputs.iter().filter(|u| u.value == SMALL.to_string()).count();
            let p = inputs.iter().filter(|u| u.value == BOX.to_string()).count();
            format!("{} boxes ({m} mixed of 4.71 ₳, {p} plain of 9.71 ₳)", inputs.len())
        };
        let mut wrong = Vec::new();
        for (name, purpose, pay) in spends {
            let h = histories(purpose.clone(), &known);
            let (apart, blind) = if pay.is_empty() {
                let one = std::slice::from_ref(&seedelf);
                (build::transfer_apart(&w.chain, &available, &h, one, &w.owner, w.signer).unwrap(),
                 build::transfer(&w.chain, &available, one, &w.owner, w.signer).unwrap())
            } else {
                (build::sweep_many_apart(&w.chain, &available, &h, &pay, &w.owner, w.signer).unwrap(),
                 build::sweep_many(&w.chain, &available, &pay, &w.owner, w.signer).unwrap())
            };
            let (spent, fewest) = (apart.inputs(), blind.inputs());
            let (fee, fewest_fee) = (apart.estimate().unwrap().fee.total, blind.estimate().unwrap().fee.total);
            let line = format!(
                "{name}: spent {} (merged {} classes, fee {fee}); {} pay (fee {fewest_fee}): {} lovelace more fee",
                describe(&spent), h.merged(&spent).len(), describe(&fewest), fee as i64 - fewest_fee as i64);
            println!("{line}");
            if spent.len() > fewest.len() { wrong.push(line); }
        }
        assert!(wrong.is_empty(), "a merge spent more boxes together than pay:\n{}", wrong.join("\n"));
    }
