    /// l4docs#3: past what one transaction spends of the small UTxOs, merge order c brings forward the largest box.
    #[test]
    fn past_one_transactions_small_utxos_a_payment_takes_a_mixed_box_before_one_of_unknown_making() {
        let w = world();
        const SMALL: u64 = 1_500_000;
        let least = wallet_minimum_lovelace_with_assets(&w.chain.params, Assets::new()).unwrap();
        assert!(SMALL >= least, "a small UTxO holds at least a Seedelf UTxO's least, {least}");
        let small: Vec<UtxoResponse> = (0..25u64).map(|i| owned(&w, 0x50, i, SMALL, &[])).collect();
        let seedelf = Payment { register: Register::create(random_scalar()).unwrap().rerandomize().unwrap(), lovelace: 34_000_000, tokens: Assets::new() };
        let make_public = vec![AddressPayment { to: key_address(), lovelace: 34_000_000, tokens: Assets::new() }];
        let send_from = |inputs: &[UtxoResponse]| {
            build::transfer_from(&w.chain, inputs, std::slice::from_ref(&seedelf), &w.owner, w.signer)
                .and_then(|s| s.estimate()).map(|_| ())
        };
        // Why orders a and b fail: 22 small can't pay 34 ₳, and 23 are more than one transaction spends.
        assert!(build::is_short(&send_from(&small[..22]).unwrap_err()));
        assert!(build::is_too_many(&send_from(&small[..23]).unwrap_err()));
        let mut picks = Vec::new();
        for unplaced_smaller in [true, false] {
            let [(unplaced, unplaced_class), (mixed, mixed_class)] = unplaced_and_mixed(&w, unplaced_smaller, 300);
            for b in [&mixed, &unplaced] {
                let with: Vec<UtxoResponse> = std::iter::once(b.clone()).chain(small[..18].iter().cloned()).collect();
                assert!(send_from(&with).is_ok(), "a box and 18 small UTxOs pay 34 ₳");
            }
            let mut known: Vec<(&UtxoResponse, Class)> = small.iter().map(|u| (u, class("public:0", Origin::Own))).collect();
            known.push((&unplaced, unplaced_class));
            known.push((&mixed, mixed_class));
            let available: Vec<UtxoResponse> = known.iter().map(|(u, _)| (*u).clone()).collect();
            let spends = [
                ("a Send of 34 ₳ to a Seedelf", Purpose::Pay, None),
                ("a Make public of 34 ₳", Purpose::Pay, Some(make_public.clone())),
                ("a new session's funding of 29 ₳ and its 5 ₳ collateral", Purpose::Fund { session: Some("session:7".into()) }, Some(funding(29_000_000))),
            ];
            for (name, purpose, pay) in spends {
                let h = histories(purpose, &known);
                let inputs = match &pay {
                    None => build::transfer_apart(&w.chain, &available, &h, std::slice::from_ref(&seedelf), &w.owner, w.signer).unwrap().inputs(),
                    Some(pay) => build::sweep_many_apart(&w.chain, &available, &h, pay, &w.owner, w.signer).unwrap().inputs(),
                };
                let spent = outpoints(&inputs);
                let took = |u: &UtxoResponse| spent.contains(&format!("{}#{}", u.tx_hash, u.tx_index));
                let which = match (took(&unplaced), took(&mixed)) { (true, false) => "W", (false, true) => "X", (true, true) => "both", (false, false) => "neither" };
                picks.push(format!("{name}, W {}: {} inputs, spent {which}", if unplaced_smaller { "smaller" } else { "larger" }, inputs.len()));
            }
        }
        let boxes: Vec<String> = picks.iter().map(|p| { let (name, rest) = p.split_once(": ").unwrap(); format!("{name}: {}", rest.rsplit_once(", ").unwrap().1) }).collect();
        assert_eq!(boxes, [
            "a Send of 34 ₳ to a Seedelf, W smaller: spent X",
            "a Make public of 34 ₳, W smaller: spent X",
            "a new session's funding of 29 ₳ and its 5 ₳ collateral, W smaller: spent X",
            "a Send of 34 ₳ to a Seedelf, W larger: spent X",
            "a Make public of 34 ₳, W larger: spent X",
            "a new session's funding of 29 ₳ and its 5 ₳ collateral, W larger: spent X",
        ], "{picks:#?}");
    }
