async function plantedWayBackThenStuck(madePrivateToo: boolean) {
  const { t } = await withSession("40000000");
  await t.balances.get("preprod");
  const s1 = ownedUtxos.find((u) => (u.asset_list ?? []).some((a) => a.policy_id === CONTRACT_V1.seedelfPolicyId))!;
  const C = hash("c9");
  t.koios.addedToAccounts.push(adaBox(C, s1.inline_datum!.bytes, t.clock.now));
  t.koios.txSpends.set(C, paidBy("ee".repeat(28)));
  const lj = lovejoin(t);
  expect(((await lj.status("preprod")).pools!.find((p) => p.id === ADA)!.someoneElse ?? []).map(ref)).toEqual([ref(inAda(C))]);
  const w1 = await lj.withdrawNow("preprod", inAda(C), true);
  const e1 = (await entryOf(t, w1.txHash))!;
  expect(e1.origin).toEqual(unplaced(w1.txHash));
  const r1 = await privateRow(t, w1.txHash, e1.lovelace);
  const rows = [r1]; let m0: KoiosUtxo | undefined;
  if (madePrivateToo) {
    const M0 = hash("d0");
    await t.activity.sent("preprod", { kind: "move-in", network: "preprod", txHash: M0, submittedAt: t.clock.now, confirmations: null }, { lovelace: "3000000", origin: madePrivate(0) });
    m0 = await privateRow(t, M0, "3000000"); rows.push(m0);
  }
  t.koios.added.push(...rows); t.clock.now += 60_000; await t.balances.get("preprod", true);
  const classes = await t.activity.classes("preprod", rows);
  const wayBack = classes.get(`${r1.tx_hash}#0`)!;
  expect(wayBack).toEqual(unplaced(w1.txHash));
  if (m0) expect(classes.get(`${m0.tx_hash}#0`)).toEqual(madePrivate(0));
  const B2 = await tokenBox(t, "f1", await ownDatum(t.wallet));
  t.koios.addedToAccounts.push(B2); t.koios.params = { coins_per_utxo_size: "4800" };
  return { t, lj: lovejoin(t), r1, m0, B2, wayBack };
}

